// ── Validate & Transform ─────────────────────────────────────
const body = $input.first().json.body ?? $input.first().json;

const required = ['restaurant_id', 'qr_token', 'items'];
for (const field of required) {
  if (!body[field]) throw new Error(`Missing required field: ${field}`);
}

if (!Array.isArray(body.items) || body.items.length === 0) {
  throw new Error('items must be a non-empty array');
}

for (const item of body.items) {
  if (!item.menu_item_id || !item.dish_name || !item.unit_price) {
    throw new Error('Each item requires menu_item_id, dish_name and unit_price');
  }
  if (typeof item.qty !== 'number' || item.qty < 1) item.qty = 1;
}

const digits = String(Math.floor(Math.random() * 10000)).padStart(4, '0');
const orderId = `ORD-${digits}`;
const sessionId = body.session_id || `SES-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
const total = body.items.reduce((sum, item) => sum + (item.unit_price * (item.qty ?? 1)), 0);

return [{
  json: {
    orderId,
    sessionId,
    restaurant_id: body.restaurant_id,
    qr_token: body.qr_token,
    table_id: body.table_id ?? null,
    waiter_id: body.waiter_id ?? null,
    notes: body.notes ?? null,
    channel: body.channel ?? 'QR Mesa',
    priority: body.priority ?? 'Normal',
    eta_minutes: body.eta_minutes ?? 18,
    total,
    items: body.items
  }
}];

const data = $('Validate & Transform').item.json;
const orderId = data.orderId;

const orderItems = data.items.map(item => ({
  order_id: orderId,
  menu_item_id: item.menu_item_id,
  dish_name: item.dish_name,
  qty: item.qty ?? 1,
  unit_price: item.unit_price,
  status: 'pending'
}));

return [{ json: { orderItems, orderId, restaurant_id: data.restaurant_id, qr_token: data.qr_token } }];

// ── Validate & determine priority ────────────────────────────
const body = $input.first().json.body ?? $input.first().json;

const required = ['restaurant_id', 'qr_token', 'call_type'];
for (const field of required) {
  if (!body[field]) throw new Error(`Missing required field: ${field}`);
}

const allowedTypes = ['Camarero','Agua','Cuenta','Alergia','Pregunta','Más pan','Servilletas','Otro'];
if (!allowedTypes.includes(body.call_type)) {
  body.call_type = body.call_type.slice(0, 50);
}

let priority = body.priority ?? 'Normal';
if (body.call_type === 'Alergia') priority = 'Crítica';
else if (body.call_type === 'Cuenta' || body.call_type === 'Camarero') priority = 'Alta';

const callId = 'C-' + Math.random().toString(36).slice(2, 10).toUpperCase();

let tableStatus = 'Camarero ocupado';
if (body.call_type === 'Cuenta') tableStatus = 'Solicita cobro';

return [{
  json: {
    callId,
    restaurant_id: body.restaurant_id,
    qr_token: body.qr_token,
    table_id: body.table_id ?? null,
    session_id: body.session_id ?? null,
    waiter_id: body.waiter_id ?? null,
    call_type: body.call_type,
    priority,
    message: body.message ?? null,
    source: 'mesa',
    tableStatus
  }
}];

// ── Validate bill request payload ────────────────────────────
const body = $input.first().json.body ?? $input.first().json;

const required = ['restaurant_id', 'qr_token'];
for (const field of required) {
  if (!body[field]) throw new Error(`Missing required field: ${field}`);
}

const callId = 'C-' + Math.random().toString(36).slice(2, 10).toUpperCase();

const paymentMethod = body.payment_method ?? null;
let message = 'Solicita la cuenta';
if (paymentMethod) {
  const allowed = ['Efectivo', 'Tarjeta', 'Transferencia'];
  if (allowed.includes(paymentMethod)) message = `Solicita la cuenta - Pago: ${paymentMethod}`;
}

return [{
  json: {
    callId,
    restaurant_id: body.restaurant_id,
    qr_token: body.qr_token,
    table_id: body.table_id ?? null,
    session_id: body.session_id ?? null,
    waiter_id: body.waiter_id ?? null,
    message
  }
}];

// ── Validate rating and sanitize comment ─────────────────────
const body = $input.first().json.body ?? $input.first().json;

if (!body.restaurant_id) throw new Error('Missing required field: restaurant_id');

const rating = parseInt(body.rating, 10);
if (isNaN(rating) || rating < 1 || rating > 5) throw new Error('rating must be an integer between 1 and 5');

let comment = null;
if (body.comment && typeof body.comment === 'string') {
  comment = body.comment
    .replace(/<[^>]*>/g, '')
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '')
    .trim()
    .slice(0, 1000);
  if (comment.length === 0) comment = null;
}

const allowedSources = ['table_qr', 'admin', 'whatsapp', 'email'];
const source = allowedSources.includes(body.source) ? body.source : 'table_qr';

return [{
  json: {
    restaurant_id: body.restaurant_id,
    session_id: body.session_id ?? null,
    table_id: body.table_id ?? null,
    waiter_id: body.waiter_id ?? null,
    rating,
    comment,
    source
  }
}];

// ── Validate & Prepare ──────────────────────────────────────────
const body = $input.first().json.body ?? $input.first().json;

const name  = String(body.name  ?? '').trim();
const email = String(body.email ?? '').trim().toLowerCase();
const phone = String(body.phone ?? '').trim();

if (!name)  throw new Error('El nombre es requerido');
if (!email) throw new Error('El correo es requerido');
if (!/^[^@]+@[^@]+\.[^@]+$/.test(email)) throw new Error('Correo inválido');

return [{ json: { name, email, phone } }];

