// ── Validate payload ─────────────────────────────────────────
const body = $input.first().json.body ?? $input.first().json;

const required = ['restaurant_id', 'name', 'email', 'password', 'role'];
for (const field of required) {
  if (!body[field] || String(body[field]).trim() === '') throw new Error(`Missing required field: ${field}`);
}

const validRoles = ['admin', 'camarero', 'cocina', 'caja'];
if (!validRoles.includes(body.role)) throw new Error(`Invalid role. Must be one of: ${validRoles.join(', ')}`);

if (!/^[^@]+@[^@]+\.[^@]+$/.test(body.email)) throw new Error('Invalid email address');

if (String(body.password).length < 8) throw new Error('Password must be at least 8 characters');

return [{
  json: {
    restaurant_id: body.restaurant_id.trim(),
    name:          body.name.trim(),
    email:         body.email.trim().toLowerCase(),
    password:      body.password,
    role:          body.role,
    pin_hash:      body.pin_hash  || null,
    shift:         body.shift     || null,
    phone:         body.phone     || null
  }
}];

const res = $input.first().json;
if (res.error || res.msg) throw new Error(res.msg ?? res.error ?? 'Auth user creation failed');
if (!res.id) throw new Error('Auth user creation failed: no user ID returned');

const prev = $('Validate Staff Payload').item.json;
return [{ json: { ...prev, auth_user_id: res.id } }];

