// ── Validate & Prepare ───────────────────────────────────────
const body = $input.first().json.body ?? $input.first().json;

const required = ['restaurantName', 'ownerName', 'ownerEmail', 'ownerPassword'];
for (const field of required) {
  if (!body[field] || String(body[field]).trim() === '') throw new Error(`Missing required field: ${field}`);
}

if (!/^[^@]+@[^@]+\.[^@]+$/.test(body.ownerEmail)) throw new Error('Invalid email address');

const baseSlug = body.restaurantName
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 40);

const suffix = Math.random().toString(36).slice(2, 6);
const restaurantId = `${baseSlug}-${suffix}`;

return [{
  json: {
    restaurantId,
    restaurantName: body.restaurantName.trim(),
    legalName:      body.legalName?.trim()    || body.restaurantName.trim(),
    rut:            body.rut?.trim()          || null,
    address:        body.address?.trim()      || null,
    phone:          body.phone?.trim()        || null,
    website:        body.website?.trim()      || null,
    ownerName:      body.ownerName.trim(),
    ownerEmail:     body.ownerEmail.trim().toLowerCase(),
    ownerPassword:  body.ownerPassword,
    plan:           body.plan || 'starter'
  }
}];

const rid = $('Validate & Prepare').item.json.restaurantId;

const tables = [
  { table_number: 1, label: 'Mesa 1', zone: 'Salón',   qr_token: `${rid}-T1` },
  { table_number: 2, label: 'Mesa 2', zone: 'Salón',   qr_token: `${rid}-T2` },
  { table_number: 3, label: 'Mesa 3', zone: 'Salón',   qr_token: `${rid}-T3` },
  { table_number: 4, label: 'Mesa 4', zone: 'Terraza', qr_token: `${rid}-T4` },
  { table_number: 5, label: 'Mesa 5', zone: 'Terraza', qr_token: `${rid}-T5` }
];

return tables.map(t => ({ json: { restaurant_id: rid, ...t } }));

const allItems = $input.all();
const last = allItems[allItems.length - 1];
return [{ json: last.json }];

